from pathlib import Path
import argparse
parser=argparse.ArgumentParser()
parser.add_argument("--cloud",action="store_true",help="Inclure la configuration Supabase publique dans le HTML autonome")
args=parser.parse_args()
root=Path(__file__).resolve().parents[1]
html=(root/'index.html').read_text()
css=(root/'style.css').read_text()
reminderDates=(root/'reminder-dates.mjs').read_text().replace('export const','const').replace('export function','function')
domain='\n'.join(line for line in (root/'domain.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
reportLogo=(root/'assets/report-logo.mjs').read_text().replace('export const','const')
pdfFonts=(root/'assets/report-fonts.mjs').read_text().replace('export const','const')
lifecycle=(root/'lifecycle-import.mjs').read_text().replace('export function','function')
lifecycle='\n'.join(line for line in lifecycle.splitlines() if not line.startswith('import '))
digest='\n'.join(line for line in (root/'digest.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
controllers=(root/'controllers.mjs').read_text().replace('export function','function')
ownership=(root/'ownership.mjs').read_text().replace('export function','function')
searchable=(root/'searchable-select.mjs').read_text().replace('export function','function')
apave='\n'.join(line for line in (root/'apave.mjs').read_text().replace('export async function','async function').replace('export function','function').replace('export const','const').splitlines() if not line.startswith('import '))
shiftCalendar='\n'.join(line for line in (root/'shift-calendar.mjs').read_text().replace('export function','function').replace('export const','const').splitlines() if not line.startswith('import '))
shiftCalendarUI='\n'.join(line for line in (root/'shift-calendar-ui.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
namingReviewUI='\n'.join(line for line in (root/'nomenclature-ui.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
apaveActionsImport='\n'.join(line for line in (root/'apave-actions-import.mjs').read_text().replace('export async function','async function').replace('export function','function').splitlines() if not line.startswith('import '))
maintenanceActionRules=(root/'maintenance-action-rules.mjs').read_text().replace('export function','function')
maintenanceTracking=(root/'maintenance-tracking.mjs').read_text().replace('export function','function')
maintenanceTrackingUI='\n'.join(line for line in (root/'maintenance-tracking-ui.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
maintenanceKpi=(root/'maintenance-kpi.mjs').read_text().replace('export function','function')
maintenanceKpiUI='\n'.join(line for line in (root/'maintenance-kpi-ui.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
maintenanceRecords=(root/'maintenance-records.mjs').read_text().replace('export function','function')
maintenanceActions='\n'.join(line for line in (root/'maintenance-actions.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
maintenanceUI='\n'.join(line for line in (root/'maintenance-ui.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
reminderModules='\n'.join('\n'.join(line for line in (root/name).read_text().replace('export async function','async function').replace('export function','function').splitlines() if not line.startswith('import ')) for name in ['reminder-contacts.mjs','reminder-plan.mjs','reminder-worker.mjs','reminder-ui.mjs'])
workspaceNavigation='\n'.join(line for line in (root/'workspace-navigation.mjs').read_text().replace('export function','function').splitlines() if not line.startswith('import '))
personnelModules='\n'.join('\n'.join(line for line in (root/name).read_text().replace('export function','function').splitlines() if not line.startswith('import ')) for name in ['personnel.mjs','personnel-ui.mjs'])
app='\n'.join(line for line in (root/'app.js').read_text().splitlines() if not line.startswith('import '))
cloud=(root/'cloud.mjs').read_text().replace('export function','function').replace('export class','class')
tracking=(root/'tracking-import.mjs').read_text().replace('export function','function')
tracking='\n'.join(line for line in tracking.splitlines() if not line.startswith('import '))
naming=(root/'nomenclature.mjs').read_text().replace('export function','function')
excel='\n'.join(line for line in (root/'excel.mjs').read_text().replace('export function','function').replace('const norm=', 'const excelNorm=').replace('norm(', 'excelNorm(').splitlines() if not line.startswith('import '))
html=html.replace('<script src="cloud-config.js"></script>','<script>'+((root/'cloud-config.js').read_text() if args.cloud else "window.VGP_CLOUD=Object.freeze({enabled:false,url:'',publicKey:'',workspaceId:''});")+ '</script>')
html=html.replace('<script src="vendor/excel.js"></script>','<script>'+(root/'vendor/excel.js').read_text()+'</script>')
html=html.replace('<link rel="stylesheet" href="style.css">','<style>'+css+'</style>')
html=html.replace('<script type="module" src="app.js"></script>','<script>'+pdfFonts+'\n'+reportLogo+'\n'+reminderDates+'\n'+domain+'\n'+tracking+'\n'+naming+'\n'+cloud+'\n'+excel+'\n'+searchable+'\n'+ownership+'\n'+controllers+'\n'+lifecycle+'\n'+digest+'\n'+apave+'\n'+shiftCalendar+'\n'+shiftCalendarUI+'\n'+apaveActionsImport+'\n'+maintenanceActionRules+'\n'+maintenanceTracking+'\n'+maintenanceTrackingUI+'\n'+maintenanceKpi+'\n'+maintenanceRecords+'\n'+maintenanceKpiUI+'\n'+maintenanceActions+'\n'+maintenanceUI+'\n'+namingReviewUI+'\n'+reminderModules+'\n'+workspaceNavigation+'\n'+personnelModules+'\n'+app+'</script>')
(root/'prototype-vgp.html').write_text(html)
